PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "calibrations" (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  sensor_id     TEXT NOT NULL,
  cp_address    TEXT,
  sensor_name   TEXT,
  serial_number TEXT,
  old_offset    REAL,
  new_offset    REAL,
  access_point  TEXT,
  quality       TEXT,
  status        TEXT,
  sensor_type   TEXT,
  zone          TEXT,
  calibrated_at TEXT,
  calibrated_by TEXT,
  server        TEXT,
  cal_cert      TEXT,
  canned_msg    TEXT,
  captured_at   TEXT DEFAULT (datetime('now')),
  UNIQUE(sensor_id, server)
);
CREATE TABLE servers (
  server      TEXT PRIMARY KEY,
  version     TEXT NOT NULL DEFAULT '3.0',
  hostname    TEXT,
  notes       TEXT,
  updated_at  TEXT DEFAULT (datetime('now'))
, customer TEXT);
CREATE TABLE exceptions (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  sensor_id   TEXT NOT NULL,
  server      TEXT NOT NULL,
  sensor_name TEXT,
  zone        TEXT,
  reason      TEXT NOT NULL,
  year        INTEGER NOT NULL,
  added_by    TEXT,
  added_at    TEXT DEFAULT (datetime('now')),
  UNIQUE(sensor_id, server, year)
);
CREATE TABLE calendar_events (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  title       TEXT NOT NULL,
  event_type  TEXT NOT NULL DEFAULT 'calibration',
  status      TEXT NOT NULL DEFAULT 'ticketed',
  customer    TEXT,
  start_date  TEXT NOT NULL,
  end_date    TEXT NOT NULL,
  ticket_id   TEXT,
  notes       TEXT,
  created_at  TEXT DEFAULT (datetime('now')),
  updated_at  TEXT DEFAULT (datetime('now'))
);
CREATE TABLE event_assignments (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id    INTEGER NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
  tech_name   TEXT NOT NULL,
  date        TEXT NOT NULL,
  UNIQUE(event_id, tech_name, date)
);
CREATE TABLE tech_events (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  tech_name   TEXT NOT NULL,
  event_type  TEXT NOT NULL,
  date        TEXT NOT NULL,
  notes       TEXT,
  UNIQUE(tech_name, date)
);
CREATE TABLE job_info (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,

  -- Identity
  customer         TEXT,
  job_name         TEXT NOT NULL UNIQUE,

  -- Equipment
  servers          TEXT,
  sensors          INTEGER,
  meters           TEXT,
  o2               INTEGER,
  server_version   TEXT,
  hardware         TEXT,

  -- Scheduling
  num_tech         INTEGER,
  active           INTEGER DEFAULT 1,
  status           TEXT DEFAULT 'Unscheduled',
  estimated_days   INTEGER,
  scheduled_with   TEXT,

  -- Location
  site_address     TEXT,
  offsites         TEXT,

  -- Contacts
  main_contact     TEXT,
  other_contacts   TEXT,
  contact_notes    TEXT,

  -- Travel
  vpn_works        TEXT,
  airport_info     TEXT,
  emerald_aisle    TEXT,
  prev_hotel       TEXT,
  hotel_comments   TEXT,
  restaurants      TEXT,

  -- Documentation
  report           TEXT,
  credentials      TEXT,
  comments         TEXT,
  other_notes      TEXT,

  -- Metadata
  primary_tech     TEXT,
  updated_at       TEXT DEFAULT (datetime('now'))
, last_calibrated DATE, scheduled_start_date TEXT, scheduled_end_date TEXT);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_calendar_history
ON calendar_events(title, start_date, end_date);
CREATE VIEW job_info_calendar_import AS SELECT     job_name,     customer,     last_calibrated,     scheduled_with,     scheduled_start_date AS start_date,     scheduled_end_date AS end_date FROM job_info WHERE scheduled_start_date IS NOT NULL   AND scheduled_end_date IS NOT NULL;
