INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(7,'Trinity Health Medical Group','Trinity Health Medical Group','802',256,'RE, HU',NULL,'G2.0',NULL,3,'FALSE','Unscheduled',NULL,'Not Scheduled','200 Jefferson Avenue Southeast, Grand Rapids, MI 49503','https://www.zeemaps.com/map/kanpr?group=5054209',NULL,NULL,NULL,'Yes','GRR','Yes','Country Inn & Suites by Radisson, Grand Rapids East, MI 3251 Deposit Dr, Grand Rapids','No issues','Wahlburgers',replace('The calibration for Trinity Health Medical Group on server 802 is complete. All 256 sensors were calibrated. 2 disabled sensors were enabled and calibrated.\nThe Hudsonville offsite has sensors that require special access and can only be opened by Kyle Baker, so please add him to the contacts for next year. His information is below:\n\nbakerkw@trinity-health.org\n616-460-2193\ndesk: 616-685-1129\n\nThere were no failures and no exceptions, and there are no issues with the hotel.\n\nAttached is the signed calibration summary.\n\nThank you!\nLeighton Solomon','\n',char(10)),'None','Lots of offsites. Zeemaps has 2024 sensor counts and correct location addresses. Contact Paul for badge access to the main site. ',NULL,NULL,'2026-08-07 15:02:34',NULL,NULL,NULL);
