INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(12,'AmeriPath Irving','AmeriPath Irving','187',21,'RE, HU',0,'G2.1','Guardian',1,'TRUE','Unscheduled',NULL,'Leighton','2501 South State Highway 121, Lewisville, TX 75067','4 Sensors at 13623 Neutron Road, WILL NEED ESCORT TO LET YOU IN',NULL,NULL,NULL,'Yes, but request account on Quest Wifi and they will email password','DFW','Yes',NULL,NULL,'Hard-8 BBQ',replace('The calibration for AmeriPath Irving on server 187 is complete. \n26 of 36 enabled sensors were calibrated.\nThere were 2 sensors with failing offsets that were not replaced. They are still not fully up and running after relocating from Irving. A lot of their sensors are not installed, and I had to troubleshoot many sensors that were installed to get them back online.\n\nThe calibration summary is attached, although the lab manager Donna has not gotten back to me with a signature.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1lnH6Tzd50_dnmTo8iwYRATT6xoOyPx0bNcyju9KBeWQ/edit?usp=sharing\n- Leighton','\n',char(10)),'None','Affiliated with Quest Diagnostics. Now relocated to Lewisville. All sensors are in main lab except two in storage room and 4 at offsite, all of which need customer to gain access.',NULL,'Leighton','2026-08-07 15:02:34','2026-04-10','2026-04-10','2026-04-10');
