INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(14,'Applied BioCode','Applied BioCode','924',42,'RE',0,'G2.0','ARMS',1,'TRUE','Unscheduled',NULL,'Daniel','10370 Slusher Dr, Santa Fe Springs, CA 90670, Unit 7','None',NULL,NULL,NULL,'No, hotspot needed','LAX','Yes',NULL,NULL,NULL,NULL,'None','Easy job, 1 tech 1 day. remind contact about calibration sequence, some rooms need to be done first if not a second visit needed',NULL,'Daniel','2026-08-07 15:02:34','2026-03-12','2026-03-12','2026-03-13');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(15,'Ipsum Diagnostics','Ipsum Diagnostics','186',31,'RE, HU',0,'G2.1','Guardian',1,'FALSE','Unscheduled',NULL,'Not Scheduled','8607 Roberts Drive, Atlanta, GA 30350 Suite 250','None',NULL,NULL,NULL,'Yes, front desk has Wifi password','ATL','Yes','Holiday Inn Express Atlanta NE - I-85 Clairmont, an IHG Hotel','No issues',NULL,replace('The calibration for Ipsum Diagnostics on server 186 is complete. 25 out of 27 enabled sensors were calibrated. The 2 exceptions were 2 sensors that were enabled and troubleshooted but the AP in the room is stuck in check network and all other APs are too far.\nThere were no failures.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1gDhV4DCXJbxY6ZGFz7kPV1-561rSxn01KFOPVXw5hSA/edit?usp=sharing\n\nThank you!\nLeighton Solomon','\n',char(10)),'None','Service Terminated as of 2/1/26. Travel is usually combined with CHOA. Takes 1 tech half a day. Server is slow and readings may be delayed.',NULL,'Leighton','2026-08-07 15:02:34',NULL,NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(16,'Asuragen','Asuragen','243',162,'RE, HU, CO2, DP',1,'G3.0','ARMS',1,'TRUE','Unscheduled',NULL,'Leighton','2150 Woodward St, Austin, TX 78744','None',NULL,NULL,NULL,'Yes, on BT-Guest. Password: "EPICscience!"','AUS','Yes','Homewood Suites by Hilton Austin-South/Airport','Nice!','"Pinthouse brewing" right by the main site has a lot of good food. Bella Donna subs nearby is also delicious',replace('The calibration for Asuragen on server 900 is complete. All 164 enabled sensors were calibrated.\nThere was 1 humidity sensor with a failing offset that was not replaced.\nThere were no exceptions.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1cOtN3qtSyMKD8WDF0S7uPMF3TQpYgeED1JLn0Vj0l8M/edit?usp=sharing\n\nThank you,\nLeighton','\n',char(10)),'None','1 tech for about 2 full days. 1 CO2, 1 DP.',NULL,'Leighton','2026-08-07 15:02:34','2026-03-10','2026-03-09','2026-03-11');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(17,'Baptist Miami','Baptist Miami','837, 838, 937, 938, 735, 736',1044,'RE, HU, CO2',0,'Mix','Mix',8,'TRUE','Unscheduled',NULL,'Not Scheduled','8900 N Kendall Dr, Miami, FL 33176','https://www.zeemaps.com/map/keexr?group=5118637',NULL,NULL,NULL,'Yes on Guest Wifi','MIA','Yes','Hampton Inn Miami Dadeland','No issues','Palacio de los Jugos, La Camaronera',replace('The calibration was a success. There are 7 failed sensors and 57 exceptions. It took 8 technicians to complete this job.\nThe Logistics were terrific! Please keep them the same for the coming years.\nI''ve emailed Matty the summary with a signature request, but she hasn''t returned it yet. I''ve attached an unsigned copy to this email.\n\nVisualizer: https://docs.google.com/spreadsheets/d/12CgY1UD2dYKOxIXV-9ryAc2UsoAaVXsqh7CwZKyaAcU/edit?usp=sharing \n\nThanks,\nBissen','\n',char(10)),'Vendormate','Just 3 Co2, 48 CPs in check as of 2025. All hands on deck. Lots of offsites, see Zeemaps',NULL,'Bissen','2026-08-07 15:02:34','2025-10-23',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(18,'Baxter/Synovis','Baxter/Synovis','681',77,'RE, HU',1,'G2.1','Mix',2,'TRUE','Unscheduled',NULL,'Leighton, Kyle','2575 University Ave W, St Paul, MN 55114, Suite 180 and 190','439 Industrial Lane, Birmingham, AL',NULL,NULL,NULL,'No, Hotspot Needed','MSP, BMH','Yes','Hampton Inn & Suites Minneapolis University Area','No issues',NULL,replace('​The calibration for Synovis on server 681 is complete. 76 out of 78 enabled sensors were calibrated.\nThe exceptions were the O2 sensor which had not yet arrived, and a sensor in Switzerland that I couldn''t calibrate for obvious reasons.\nThere were 8 sensors to calibrate in in Birmingham, the rest were in St. Paul.\nHotel was excellent for St. Paul.\nThe signed calibration summary is attached.\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1pqQm9VN1gmQpDEFvQ3-dEqzuWn0Cg3rypmtxFsw9rHo/edit?usp=sharing\nThank you!','\n',char(10)),'None','21 sensors at offsite which is likely done by another tech because its in Birmingham Alabama. 1 O2 sensor. St Paul location is in Baxter building, takes 1 tech 1 day. Heavy PPE in clean rooms',NULL,'Leighton','2026-08-07 15:02:34','2026-04-28','2026-04-27','2026-04-29');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(19,'Baxter/Synovis NY','Baxter/Synovis NY','679',61,'RE, HU',0,'G3.0','Guardian',1,'TRUE','Unscheduled',NULL,'Matt','711 Park Ave, Medina, NY 14103 Suite 201',NULL,NULL,NULL,NULL,NULL,'BUF','Yes',NULL,NULL,NULL,'New Install','None','After signing in at the front desk, you will have to watch a 15-20 minute video on work place safety.',NULL,'Bissen','2026-08-07 15:02:34','2026-04-28','2026-04-27','2026-04-28');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(20,'Baylor College of Medicine ','Baylor College of Medicine ','253, 254',312,'RE, HU, CO2, DP',3,'G2.1','ARMS',2,'TRUE','Unscheduled',NULL,'Joey, Dejan','1102 Bates Avenue, Houston, TX 77030 ','None',NULL,NULL,NULL,'No, hotspot needed','IAH, HOU','Yes','Hyatt House Houston Medical Center','No issues',NULL,replace('Ana,\nThank you very much for your help this week. Attached you can find your 2025 Isensix Calibration Reports for each server, as well as a calibration summary. \n309 out of your 311 sensors were calibrated, with the two exceptions being the freezer that is not in use and the only O2 sensor we did not replace with one of your spares. \nThe calibration certificates for the meters used during your calibrations can be found at "Setup" > "Media".\nPlease let us know if you have any questions regarding your calibrations or need any further assistance.     \nThank you, Leighton','\n',char(10)),'None','EMAIL ANA 2 WEEKS AHEAD TO ALLOW VPN TO WORK ON WIFI. All on 16th Floor of Feigin Building. Pretty much everything is in clean rooms. Expect to spend two full days in heavy PPE. All meters are needed. Takes 2 techs 3 days',NULL,'Leighton','2026-08-07 15:02:34','2025-09-09','2026-09-08','2026-09-11');
