INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(29,'Case Western','Case Western','185',84,'RE, HU',0,'G2.1','Guardian',1,'TRUE','Unscheduled',NULL,'Matt','2085 Adelbert Road, Cleveland, OH 44106','1819 East 101st Street, Cleveland, OH',NULL,NULL,NULL,'Yes on CaseGuest','CLE','Yes','Courtyard by Marriott',NULL,'Lots of good spots at Little Italy near the site',replace('The calibration for Case Western on server 185 is complete. 80 out of 83 enabled sensors were calibrated.\nThere were no failures.\nThe three exceptions were all sensors stuck in Check Sensor.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1G6HB85huUg5MTo_O0JH4v6IzA22OdDPslcNCY2FCTQY/edit?usp=sharing\n\n\nThank you!\n- Leighton','\n',char(10)),'None','Main site is Pathology building at 2085 Adelbert. Most sensors are on 4th floor of that building. 32 Sensors (all SC) at CCMSB offsite. ',NULL,'Leighton','2026-08-07 15:02:34','2026-02-06','2026-02-02','2026-02-05');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(30,'Cell Signaling','Cell Signaling','852, 853, 854',458,'RE, HU',NULL,'G2.1','ARMS',2,1,'Unscheduled',NULL,'Fernando, Bissen','3 Trask Ln, Danvers, MA 01923',NULL,NULL,NULL,NULL,NULL,'BOS','Yes',NULL,NULL,NULL,NULL,'None',NULL,NULL,'Fernando','2026-08-07 15:02:34','2026-07-30',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(31,'Children''s Hospital of Atlanta','Children''s Hospital of Atlanta','873, 874, 875, 876',263,'RE, HU, CO2',1,'G2.1','ARMS',4,'TRUE','Unscheduled',NULL,'Joey, Fernando, Bissen','1405 Clifton Rd, Atlanta, GA 30322','https://www.zeemaps.com/map/kivka?group=5200078',NULL,NULL,NULL,'Yes on CHOA_Guest','ATL, longest TSA ever','Yes','Holiday Inn Express Atlanta NE - I-85 Clairmont, an IHG Hotel','No issues','The Original Chick-fil-A is near airport (The Dwarf House Chick-fil-A)',replace('Calibration got done on time.\nEven with some logistics problems due to weather, we managed to complete the job.\nFirst day we star on Scottish Rite 3 Techs, BEFORE Calibration was about 28 checks errors, we reduce to 10, the others are check network etc.( Scottish Rite)\n\nSecond day, we have a full crew,\n4 technicians work on Eagle stone site. And 2 we when back to the Scottish R. to finish and take care Support and CAP locations.\nFinal day 4 tech when back to Eagle S. And 2 to Huges Spalding And Meridian mark 1 Sensor Arrive before 12 noon. (pharmacy)\nHotel perfect location for this job.\n\nThank you.\nFernando.','\n',char(10)),'None',replace('Only 2 CO2 for whole job, at Scottish Rite. Egleston has a ton of sensors in check. 1 ARMS O2 on SID 874\nIt''s best if you call Cristian before anyone else; he can be incredibly helpful!','\n',char(10)),NULL,'Bissen','2026-08-07 15:02:34','2026-01-29','2026-01-26','2026-01-30');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(32,'Meadows Medical Center','Meadows Medical Center','960',2,'RE',0,'G2.0',NULL,1,'FALSE','Unscheduled',NULL,'Not Scheduled','1 Meadows Pkwy, Vidalia, GA 30474','None',NULL,NULL,NULL,'Yes on Guest_Access wifi','ATL','Yes','Home2 Suites by Hilton Vidalia','No issues','VIDALIA ONIONS!',replace('The calibration for Meadows on server 960 is complete. The 2 enabled sensors were calibrated.\nNo failures or exceptions. I already sent the main contact the full calibration report.\nThe calibration summary is attached although the contact never got back to me for a signature.\nPlease update the primary pharmacy contact Michelle Cox email to michelle.cox@healthtrustpg.com, the other email no longer works.\nThe visualizer used for this job is viewable here:\nhttps://docs.google.com/spreadsheets/d/1iTqYvq8e_3O1hhXM37L38K6EC0zjrfX6z5N6tD-AwWc/edit?usp=sharing ','\n',char(10)),'None','NO CONTRACT - All sensors but 2 are disabled, so this is the smalled job ever. 1 fridge in pharmacy, 1 SC in surgery.',NULL,'Leighton','2026-08-07 15:02:34',NULL,NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(33,'Children''s Hospital of Boston','Children''s Hospital of Boston','285, 286, 441, 442, 446',653,'RE, HU, DP',0,'Mix','Mix',8,'TRUE','Unscheduled',NULL,'Not Scheduled','300 Longwood Ave, Boston, MA 02115','https://www.zeemaps.com/map/kekrp?group=5122535',NULL,NULL,NULL,'Yes','BOS','Yes','Hilton Garden Inn 110 Royall St. Canton, MA. 02021','1 hour from Main site','Wahlburgers, Causeway',replace(' The calibration for Boston Children’s Hospital on servers 143, 144, 446, 247, and 442 is complete.  \nWe started this job with 133 sensors in Check network, check link, or check sensor. We were able to bring this number down to 87 in check by the end of the job but it was no small task. Persistent construction of the hospital in addition to lack of Isensix maintenance by the hospital staff made this job extremely difficult.  About 1 in 3 sensors we would encounter had some issue (check network, check sensor, unplugged, moved, etc) that we had to fix in addition to being calibrated. Additionally, about half of all sensors lacked glycol in the bottle or had no bottle altogether. \n\nAll contacts stated they had no idea we were coming, leading to them scrambling to find escorts for us and delaying our start on Tuesday morning. \n\n481 sensors out of 567 enabled sensors were calibrated, meaning we had 86 exceptions. The reasons for these exceptions are listed in the calibration summary attached. For the most part, it was sensors stuck in check network and areas we had no access to.  \n\nBecause of all these issues, it took 6 techs 3 full days as well as half of Monday to get the calibration done, leaving little time to troubleshoot the huge number of issues on these servers. \n \nThere were 11 failures that were not replaced.  \n\nThe hotel and location are less than ideal. Not sure if this is a recent development, but the area we were in is now a very rough part of town and we all saw some very sketchy activities throughout our stay. \n\nWe think it would be a good idea to have a second visit to this job just for maintenance, because all the guys agree that this is probably the job with the most issues any of us have encountered. \n\nIf we have a second visit for maintenance, we should ensure the customer has a full inventory and have their IT department on board to fix the network issues. \n\nThe offsite addresses were also not listed in the contact info, so if we could please request these from James West and include them for next year. \n\nFinally, if we can add Stephen Fostello (stephen.fostello@childrens.harvard.edu) as an additional main contact for this job, as he now covers all of Nourishment. James West still covers all of Pharmacy. \n\nThe signed calibration summary is attached. Group Leader Alan Arruda signed because James West was out on Thursday.\n\nThank you! \n\nLeighton Solomon','\n',char(10)),'Vendormate','Lots of construction and a LOT of sensors in Check. Most bottles do not have glycol. 43 exceptions for 2024',NULL,'Fernando','2026-08-07 15:02:34','2025-10-30',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(34,'Children''s Hospital San Diego','Children''s Hospital San Diego','362',341,'RE, HU',2,'ARMS','ARMS',2,'TRUE','Unscheduled',NULL,'Daniel, Dejan','3020 Children''s Way, San Diego, CA 92123','https://www.zeemaps.com/map/kbpqw?group=5073168',NULL,NULL,NULL,'Yes','SAN','Yes','Four Points by Sheraton San Diego 8110 Aerodrive Dr, San Diego ','Best location possible',NULL,NULL,NULL,'Escort is needed and confirmed Offsites ahead of time, also 2 Oxygen sensors on the server.','LEGACY CUSTOMER','Dejan','2026-08-07 15:02:34','2025-08-13','2026-08-24','2026-08-28');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(35,'Children''s National','Children''s National Phase 1','780, 781, 778, 779, 789',762,'RE, HU, CO2',4,'G2.1','Mix',8,'TRUE','Unscheduled',NULL,'Daniel, Joey, Fernando, Matt, Bissen, Kyle, Dejan','111 Michigan Ave NW, Washington, DC 20010','https://www.zeemaps.com/map?group=4963840',NULL,NULL,NULL,'Yes','DCA, IAD','Yes','Holiday Inn Express Washington DC N-Silver Spring, an IHG Hotel','No issues, just not the best area','La Casita',replace('The field service technicians completed this job over the course of a week. Those who arrived early on Monday worked at offsite locations. On Tuesday and Wednesday, one technician continued handling offsite tasks while the rest focused on the main hospital. By Thursday, the entire team finished the remaining offsite locations.\n\nThere were 16 exceptions and 11 failures, primarily due to lack of access, ongoing construction, or damaged sensors.\n\nAdditionally, the oxygen sensor Biorepository_CNRIC_O2 Monitor was still in transit on Friday and was not replaced.\n\nPlease let us know if you have any questions.\n\nVisualizer: https://docs.google.com/spreadsheets/d/1ygEHkoJM1h4PiupBPNZR0juiKjBlqPXfQ0lfGkH1taY/edit?usp=sharing\n\n\nThanks,\nBissen Cazenueve','\n',char(10)),'Green Security',replace('-All techs\n-Two O2 sensors & 1 CO2\n-Lots of patient rooms with at least 1 sensor each\n-SZI (Sheikh Zayed Institute) is at main site 6th FL (SID 789)\n-Research has units on 3.5, 5th and 6th floors\n-Do not calibrate Research equipment without their presence or assistance!\n-Names w/ phone #''s printed on Research freezers are not the actual department contacts','\n',char(10)),NULL,'Fernando','2026-08-07 15:02:34','2026-02-19','2026-02-16','2026-02-20');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(36,'Children''s National','Children''s National Phase 2','788',294,'RE, HU, CO2',5,'G2.1','Mix',2,'TRUE','Unscheduled',NULL,'Not Scheduled','111 Michigan Ave NW, Washington, DC 20010','https://www.zeemaps.com/map/kgpoi?group=5160982#',NULL,NULL,NULL,'Yes','DCA, IAD','Yes',replace('Fairfield by Marriott Inn & Suites Washington, DC/New York Avenue\n','\n',char(10)),'No issues','La Casita, Andy''s Pizza by hotel downtown is good!',replace('The calibration for Children''s National Phase 2 on server 788 is complete. All 306 enabled sensors were calibrated.\nThere were was 4 failures.\nThere were no exceptions.\n2 techs did the job in 3 full days.\n\nThe offsites provided by the contact have no separation between phase 2 and phase 1, so we created a new zeemap, and based on the visualizer determined where we actually had to go for this phase. There is a lot of crossover between offsites on each phase. I understand the customer wants sensors separated based on server and zone, but logistically it makes more sense to have sites unique to each phase, instead of going to 3 of them twice a year. Otherwise, we have to drive an hour to the same site twice for 4 sensors one phase and 2 sensors the next phase. Not sure what the solution is but there has to be a more cost effective way.\n\nPhase 2 Zeemap: https://www.zeemaps.com/map/kgpoi?group=5160982#\nPhase 1 Zeemap: https://www.zeemaps.com/map/jvjxy?group=4963840\n\n\nKen reached out to Andy but has not yet received a signature. The unsigned Calibration Summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/16V_DprRA53cszk9LYPLenu2qopvHswsjOKtk1nlpAZM/edit?gid=2090746632#gid=2090746632\n\nThanks!\n\n- Leighton','\n',char(10)),'Green Security','2 techs, 3 days onsite. 11 CO2. 5 O2. 90% of the job is in the lab on floor 2 at main site. 4 offsites, see Zeemaps',NULL,'Fernando','2026-08-07 15:02:34','2025-11-20',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(37,'CHLA','CHLA','791, 792, 793, 794',819,'RE, HU, CO2, DP',0,'Mix','Mix',5,'TRUE','Unscheduled',NULL,'Daniel, Joey, Fernando, Bissen, Dejan','4650 Sunset Boulevard, Los Angeles, CA 900274','7 Offsites',NULL,NULL,NULL,'Yes','LAX','Yes','Aventura Hotel 1020 Fedora St, Los Angeles, CA 90006',NULL,NULL,NULL,'Green Security','Coordinate a game plan ahead of time for visiting Offsites and provide a logistic for main site as well, Saban and SRT needs escort 100% ',NULL,'Daniel','2026-08-07 15:02:34','2026-02-12','2026-02-09','2026-02-13');
