INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(40,'Coastal Bend Blood Center','Coastal Bend Blood Center','412',42,'RE, HU',0,'G3.0','Mix',1,'TRUE','Unscheduled',NULL,'Leighton','209 North Padre Island Drive, Corpus Christi, TX 78406','None',NULL,NULL,NULL,'Yes','CRP','No','Holiday Inn Corpus Christi Arpt & Conf Ctr','No issues',NULL,replace('Nicole,\nThank you so much for your help this week!\nAttached please find your 2026 Isensix Calibration Summary and Report. The calibration certificates for the meters used during your calibrations can be found at "Setup" > "Media". \nThe mapping sensors have been disabled but all stored data is on the server for you to access at your convenience. The walk-in freezer will have valid readings up until 8 am 3/13/2026 at which point the sensors were removed, and the walk-in fridge will have valid readings until 8:30 am.\nPlease let us know if you have any questions regarding your calibrations or need any further assistance.     \nThank you, ','\n',char(10)),'None','Every other year you''ll have to do mapping in walk in fridge and freezer. Mapping last done in 2026. Place sensors in each corner of walk ins, let them sit for 24 hrs, then remove and send them back to isensix. The regular calibration is straightforward. ',NULL,'Leighton','2026-08-07 15:02:34','2026-03-12','2026-03-12','2026-03-13');
