INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(45,'CTS Dallas Bedford & St. Louis','CTS Dallas Bedford & St. Louis','718',93,'RE, HU',0,'G2.1','Guardian',1,'TRUE','Unscheduled',NULL,'Leighton, Matt','2205 Hwy 121, Bedford, TX 76021','13610 Riverport Dr, Maryland Heights, MO 63043',NULL,NULL,NULL,'Yes on CTS Guest, Password: "Connect2Awe"','DFW, STL','Yes',NULL,NULL,NULL,replace('The calibration for CTS Bedford and CTS St. Louis on server 709 is complete. 104 total sensors were calibrated, with 5 disabled after calibration.\nThere were no failures or exceptions.\n\nThe signed calibration summaries are attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1g91HuDz2w7duVRMqPTe5Njc-oI0PzjVQf05iWAuYOe0/edit?usp=sharing\n\nThank you!\nLeighton','\n',char(10)),'None','CTS Central server. 40 sensors in Bedford, TX and 60 in St. Louis. Server is consistently about 10 minutes delayed on readings. They tend to enable a lot of sensors to calibrate while you''re there and the will disable afterwards',NULL,'Leighton','2026-08-07 15:02:34','2026-02-13','2026-02-09','2026-02-13');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(46,'CTS East Coast','CTS East Coast','717',126,'RE, HU',0,'G2.1','Guardian',2,'TRUE','Unscheduled',NULL,'Leighton, Kyle','13500 South Point Boulevard, Charlotte, NC 28273 Suite A','10100 Dr M.L.K. Jr St N, St. Petersburg, FL 33716',NULL,NULL,NULL,'No, Hotspot Needed','CLT, TPA','Yes',replace('(CLT) TownePlace Suites Fort Mill at Carowinds Blvd.\n(TPA) Homewood Suites by Hilton St. Petersburg Clearwater','\n',char(10)),'No issues',NULL,replace('The calibration for CTS East Coast Charlotte on server 707 is complete. All 76 enabled sensors were calibrated. The rest of the sensors on the server are in Tampa and will be sent in a separate report from Fernando.\n1 tech did the job in a day and half.\nThere were no failures and no exceptions.\nHotel was great.\nThe confirmation email stated they may not want calibration stickers but they requested we do put stickers on the calibrated sensors so I did. \n\nPlease send the final calibration report to Jennifer Sellers as well at jsellers@mycts.org.\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1GdY_zgNbCdwCo53kfX_g7hdI6-W1jaVLL2nw9nP3t5M/edit?usp=sharing\n\nThank you!\nLeighton','\n',char(10)),'None','76 sensors in Charlotte, NC, 55 sensors in Tampa, FL. Basically two different jobs but both are on server 717. ',NULL,'Bissen','2026-08-07 15:02:34','2026-06-15','2026-06-08','2026-06-12');
