INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(71,'LAC USC (LA General)','LAC USC (LA General)','354, 355',386,'RE, HU, CO2',0,'G3.0','Mix',2,'TRUE','Unscheduled',NULL,'Not Scheduled','1950 Marengo Street, Los Angeles, CA 90033','See visualizer, LAC USC Calibration Visualizer v4.5',NULL,NULL,NULL,'Yes on Guest Wifi','LAX','Yes','Hyatt House La - University Medical Center','Pretty nice!','Grand Central Market has a LOT of good food in one area',replace('Please find attached a copy of the Summary and Failed Log, sensor was not replaced, out of warranty, also for the following year since Pharmacy is the Department with the most number of sensors I would reach out to them for scheduling, they must provide an escort for a minimum of 2 if not 3 days (Kevin Weissman - kvweissman@dhs.lacounty.gov), sensors are all over 3 different buildings also on every floor, some of the Access Points on Check Network and I was not able to get a point of contact, included all the persons below in the Full Calibration Report, a minimum of 3 Technicians is needed to complete the job,\n\n \nPoint of contacts requesting Full Calibration Report=\n\nServer ID\n\nZone\n\nContact Information\n\n352 - 353\n\nBlood Bank\n\nChris Tuma - ctuma@dhs.lacounty.gov\n\n352\n\nCORE LAB (New Hospital) - CORE LAB GH\n\nStephan Tanphanich - stanphanich@dhs.lacounty.gov\n\n352\n\nEL MONTE PHARMACY - EL MONTE PHARMACY VACCINE\n\nWilbert Ho - WHo@dhs.lacounty.gov\n\n352\n\nHUDSON CHC PHARMACY\n\nKevin Yamanouye - kyamanouye@dhs.lacounty.gov\n\n352 - 353\n\nLAB ANATOMIC PATHOLOGY - Morgue\n\nJonathan Naritoku - jnaritoku@dhs.lacounty.gov\n\n352 - 353\n\nPharmacy\n\nKevin Weissman - kvweissman@dhs.lacounty.gov\n\n352\n\nPHARMACY/2P82\n\nSandy Leem - sleem@dhs.lacounty.gov\n\n352\n\nROYBAL CHC PHARMACY\n\nTuan Trinh - ttrinh@dhs.lacounty.gov\n\n353\n\nAnesthesiology Department\n\nTim Vale - tvale@lacusc.org\n\n353\n\nDietary\n\nAndrew Cosgrove - andrewcosgrove@iammorrison.com\n\n353\n\nLAB APCrypt\n\nEstela Inouye - einouye@dhs.lacounty.gov\n\n353\n\nLab/Micro Lab\n\nLeang Tea - ltea@dhs.lacounty.gov\n\n \n\nThe following contact needs a Full Training Session Jonathan Naritoku - jnaritoku@dhs.lacounty.gov he oversees 2 different Zones in on both Servers LAB ANATOMIC PATHOLOGY – Morgue,\n\n \nThank you,\nDaniel Recions','\n',char(10)),'Vendormate','4 CO2 in lab, see visualizer for offsites',NULL,'Daniel','2026-08-07 15:02:34','2025-11-06',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(72,'LifeServe BCI','LifeServe BCI','402',146,'RE, HU',0,'G2.1','Mix',1,'TRUE','Unscheduled',NULL,'Dejan','5625 Northwest Johnston Drive, Johnston, IA 50131','https://www.zeemaps.com/map/jyqta?group=5021172',NULL,NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Fernando','2026-08-07 15:02:34','2026-06-25','2026-06-22','2026-06-26');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(73,'LifeSouth ','LifeSouth ','256',418,'RE, HU, CO2, DP',6,'G2.1','Guardian',3,'TRUE','Unscheduled',NULL,'Not Scheduled','4039 Newberry Rd, Gainesville, FL 32607','https://www.zeemaps.com/map/kcjsj?group=5086727',NULL,NULL,NULL,'Most sites yes, some need hotspot','ATL, BHM, Probably Ocala for Florida','No','Several throughout','No issues',NULL,replace('We''ve completed the calibration. Two sensors failed: the BIRM IRL Refrigerator iSeries and the HERN Freezer. (The BIRM IRL Refrigerator iSeries did not actually fail; the client misconfigured the sensor during installation.) They also installed the O2 sensors before the calibration.\n\nWe accidentally missed the site in Harvest because it was not on the contact sheets; TOFTO, Columbus, and Harvest were not listed. \n\nThe logistics for the Florida portion were great! Please keep them the same if possible.\nI''ve CC''d the other techs on this email in case they have suggestions.\nI sent Teresa the summary with a signature request, but she hasn''t returned it yet. I''ve attached an unsigned copy.\n\nVisualizer: https://docs.google.com/spreadsheets/d/1jRyGhYa-UlZ2mGFb7mVdYroebZfkIGxuQu47sHKBxpY/edit?usp=sharing\n\nThanks,\nBissen','\n',char(10)),'None','LOTS of driving. Covers 3 states, one tech per state. Alabama, Georgia, and Florida. PLEASE, email Teresa your route plan in advance! DP and CO2 meters only needed for Florida Tech.  Alabama tech should set their timezone to Eastern time as server is EDT. Up to date addresses for locations can be found on customer website here: https://donors.lifesouth.org/donor/schedules/geo',' LifeSouth Isensix Calibration Visualizer v4.2','Bissen','2026-08-07 15:02:34','2025-09-25',NULL,NULL);
