INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(75,'MBC / Innovative Blood','MBC / Innovative Blood','872',246,'RE, HU',0,'ARMS','ARMS',2,'TRUE','Unscheduled',NULL,'Joey, Fernando','737 Pelham Boulevard, St Paul, MN 55114 ',replace('14 East Central Entrance, Duluth, MN\n100 N 84th St, Lincoln, NE\n12100 Pacific Street, Omaha, NE\n1631 Pine Lake Road, Lincoln, NE\n4900 North 26th Street, Lincoln, NE','\n',char(10)),NULL,NULL,NULL,'Yes','MSP, LNK','No',replace('Hampton Inn & Suites Minneapolis University Area\nCountry Inn & Suites by Radisson, Lincoln North Hotel and Conference Center, NE','\n',char(10)),'No issues','The Market at Malcolm yards, right by St. Paul hotel',replace('The calibration for MBC on server 872 is complete. All 248 enabled sensors were calibrated, with 5 sensors being disabled after calibration.\nThere were no failures and no exceptions.\nHotel was excellent.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1HI83txx0Bvg1264j3EvSnXL76Qlp4tqVhUiZm11MvoQ/edit?usp=sharing\n\nThank you!\nLeighton','\n',char(10)),'None','68 sensors near Lincoln Nebraska. 29 in Duluth, MN. The rest are in St. Paul. One tech in MN and one in NE. Pretty much every fridge, incubator, and walk-in has 3 or 4 sensors on it.',NULL,'Leighton','2026-08-07 15:02:34','2026-06-24','2026-06-22','2026-06-26');
