INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(92,'Northside Hospital Forsyth','Northside Hospital Forsyth','810, 818',489,'RE, HU',0,'G2.1','Mix',4,'TRUE','Unscheduled',NULL,'Leighton, Joey, Fernando, Kyle','1200 Northside Forsyth Drive, Cumming, GA 30041','1055 Haw Creek Parkway, Cumming, GA 30041',NULL,NULL,NULL,'Yes','ATL','Yes',replace('Hampton Inn Cumming\n 915 Ronald Regan Blvd, Cumming, GA 30041 ','\n',char(10)),'No issues','Marie''s Italian Deli, Friends Cumming Grill',replace('    All sensors got calibrated,\nNo Exceptions or Failures.\nThe original sensor count was 509 got increase to 512 few more, no problem.\nWe address few minor issues such is, Loos wires, Check links, Velcro.  Little clean up. \n\nCarolyn Stokes coordinated all the contacts,  Tina Wood Pharmacy, for next year will NEED a second escort from the pharmacy on Tuesday.\nAfter finishing the lab.\n\n Thank you .! \nFernando.        \n\nhttps://docs.google.com/spreadsheets/d/1SuZSxOdqWguKoFL_hgS2qhYhGQAQQZbsPfW3nrB5ie8/edit?gid=1716933692#gid=1716933692','\n',char(10)),'Vendormate','1 Offsite. Customer takes good care of their sensors, 500+ sensors and none in check. Will have to go at night or very early morning to do about 100 sensors in OR. L&D door codes: 67000. For SPD, take elevator from surgery 2 or 3 to basement.',NULL,'Fernando','2026-08-07 15:02:34','2026-03-19','2026-03-16','2026-03-20');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(93,'Northside, Atlanta, Duluth, Gwinett','Northside, Atlanta, Duluth, Gwinett','811, 812, 814, 815',365,'RE, HU',0,'G2.1','Guardian',3,'TRUE','Unscheduled',NULL,'Daniel, Joey, Dejan','1000 Johnson Ferry Road Northeast, Atlanta, GA 30342','https://www.zeemaps.com/map/jztis?group=5040508',NULL,NULL,NULL,'Yes','ATL','Yes',NULL,NULL,NULL,NULL,'Vendormate','1 GUY doing offsites, 2 guys Gwinett. try to do Cathlab around noon. ',NULL,'Fernando','2026-08-07 15:02:34','2026-07-23','2026-07-20','2026-07-24');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(94,'Northwestern Lake Forest Hospital','Northwestern Lake Forest Hospital','202, 205',326,'RE, HU',0,'Mix','Mix',3,'TRUE','Unscheduled',NULL,'Leighton, Fernando, Dejan','1000 North Westmoreland Road, Lake Forest, IL 60045','https://www.zeemaps.com/map/kbtvx?group=5076003',NULL,NULL,NULL,'Yes','ORD','Yes','Holiday Inn Express Chicago NW-Vernon Hills','No issues','Portillo''s',replace('Mr. Larson, \nThank you for your help this week!\nBelow is your 2025 Isensix Calibration Report.\nThere were no failures that weren''t replaced. \nThere were 4 exceptions which were patient rooms we could not gain access to.\nThe calibration certificates for the meters used during your calibrations can be found at "Setup" > "Media". ("Setup > Nist Certs" on ARMS).\nPlease let us know if you have any questions regarding your calibrations or need any further assistance.     \nLake Forest Summary 2025.pdf\nLake Forest 205 Calibration Report 2025.pdf\nLake Forest 202 Calibration Report 2025.pdf','\n',char(10)),'None','Pretty straightforward. Merle is nice and will help out. Most sensors are in the lab and pharmacy. Just 1 CO2 in lab at main site. About a dozen total offsites. Largest offsite (Grayslake) has around 70 sensors. Customer takes good care of sensors and few if any are in check.',NULL,'Fernando','2026-08-07 15:02:34','2025-08-20','2026-08-17','2026-08-21');
