INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(96,'Novant ','Novant ','135',25,'RE, CO2',0,'G2.0','Guardian',1,'TRUE','Unscheduled',NULL,'Fernando','615 Mockville Rd, Salisbury, NC 28144','NONE',NULL,NULL,NULL,'HOTSPOT','CLT','Yes','125 Marriott Circle, Salisbury, NC ','Marriott or holyday inn','NONE only fast food.  Culvers.','Just another happy custumer.','None','Small job, 2 C02 Sensors. 1 sensor in OR T wire is install, 1 sensor at the Morgue Basament main contact will call Security in order to open the door.',NULL,'Fernando','2026-08-07 15:02:34','2026-01-21','2026-01-20','2026-01-23');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(97,'NYBC (New York Blood Center)','NYBC (New York Blood Center)','277, 278, 279, 283, 346',481,'RE, HU, CO2',4,'Mix','Mix',3,'TRUE','Unscheduled',NULL,'Joey, Fernando, Bissen','601 Midland Ave Entrance 2, Rye, NY 10580','https://www.zeemaps.com/map/knkpz?group=5280677',NULL,NULL,NULL,'Yes, Guest Wifi: "guest@nybc.wifi" for email and "nybc" password','LGA, JFK, EWR','Yes',replace('NYBC HOTEL’S FOR FERNANDO\nSunday.  Hyatt place Mt. Laurel 8000 Crawford pl. Laurel NJ 08054 (1 NIGTH)\nMonday. Courtyard by Marriott Montvale 100 chestnut Ridge RD.  Montvale, NJ 07645 (1 NIGTH)\nFor the rest of the week stay at RYE,\nWestbury site Near by Hotel’s.\nHyatt place Garden city.\nHilton Garden inn Westbury.   And few more all are near a shopping center Roosvelt field mall. 10 minutes from site. 45 minutes from LGA. 30 minutes from JFK.\n','\n',char(10)),NULL,NULL,replace('All sensors got calibrated. One exception.\nWe got ask by Ray to look one the sensors over Lake success, on SID 216 CP# 25799. Now is calibrated and running in prefect conditions.\nThat was the delay with our report. Now is completed.\n\nThank you.\n Fernando.','\n',char(10)),'None',replace('Techs MUST have full inventory\nFailed or broken sensors need to be reported immediately','\n',char(10)),'LEGACY CUSTOMER','Fernando','2026-08-07 15:02:34','2026-01-14','2026-01-12','2026-01-16');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(98,'Ohio State University Medical Center','Ohio State University Medical Center','424, 426, 978, 979',709,'RE, HU, CO2, DP',8,'Mix','Mix',6,'TRUE','Unscheduled',NULL,'Leighton, Joey, Fernando, Bissen, Kyle, Dejan','410 West 10th Avenue, Columbus, OH 43210','https://www.zeemaps.com/map?group=4974695',NULL,NULL,NULL,'Yes','CMH','Yes','Hyatt House Columbus Osu / Short – North','Very nice! Big rooms with full kitchen, huge gym, grill outside','Culver''s, Nong''s Hunan Express, Budd Dairy Food Hall, Bob Evans',replace('One  02 sensor need to be replaced on JWC OR Oxygen Sensor Room 3292  G02 61.eb.3c,\nTHE NEW SENSOR G02 -0425-0002 looks is bad sensor, can you please send a replacement to main contact.\nMatthew Scheidegger\nClinical Laboratory Manager\nSpecial Functions Lab\n410 W. 10th Ave.\nS308 Rhodes Hall\nColumbus, OH 43210\nMatt.Scheidegger@osumc.edu\nPhone: (614) 293-7979\n12 Exceptions.\n1 FAIL Sensor not under warranty.\nFor next year Add one more Tech, Pharmacy will add more sensors.\nSame hotel, 3 cars\nThank you.!\nFERNANDO.','\n',char(10)),'Vendormate','6 techs, 3 full days. All DPs are at CTL lab at main site. Tell departments when any sensors fail ASAP. Ackerman site; Arrive at 8 AM (bad parking). Polaris largest offsite.',NULL,'Fernando','2026-08-07 15:02:34','2026-04-23','2026-04-20','2026-04-26');
