INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(107,'Parkland','Parkland','470, 471, 974, 976',291,'RE, HU',0,'Mix','ARMS',3,'TRUE','Unscheduled',NULL,'Leighton, Joey, Kyle','5200 Harry Hines Boulevard, Dallas, TX 75235','https://www.zeemaps.com/map/jukbn?group=4946357',NULL,NULL,NULL,'Yes on guest wifi','DFW','Yes','Homewood Suites by Hilton Dallas-Market Center',NULL,NULL,replace('The calibration for Parkland on servers 470, 471, 974, 976 is complete.\n247 out of 278 enabled sensors were calibrated. One exception was due to no access to the unit, and the rest are sensors at the Dallas County Jail that we usually do not calibrate.\nThere were 9 sensors with failing offsets that were not replaced. Most of these also failed last year, and some failed 3 or more years in a row and still have not been replaced.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1jsWNtcQATj4vup9ivc3wyqvm6eFFw0YrJ-vz8uI8EGw/edit?usp=sharing\n\nZeemaps: \nhttps://www.zeemaps.com/map?group=4946357#\n\nThank you! - Leighton','\n',char(10)),'None',replace('More than half the job is offsites. Need to get badge from Police Department, which is next to Shabretta at 5223 Tex Oak Avenue, the Parkland Logistics Building. Many sensors are in Dallas County Jail but we don''t calibrate them all. At offsites, WISH fridges are in pharmacy rooms, there is usually a humidity at each lab.\n***Shabeitta has to set up an appointment for the county jail calibration***','\n',char(10)),NULL,'Leighton','2026-08-07 15:02:34','2026-03-25','2026-03-23','2026-03-27');
