INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(119,'Quest','Quest Houston','932',123,'RE, HU, CO2',0,'G2.0','Guardian',1,'TRUE','Unscheduled',NULL,'Kyle','5850 Rogerdale Road, Houston, TX 77072','None',NULL,NULL,NULL,'Yes, but request account on Quest Wifi and they''ll email password','IAH, HOU','Yes','SpringHill Suites by Marriott Houston Westchase','Very nice and VERY close by!',NULL,replace('The calibration for Quest Houston on server 932 is complete. All 113 enabled sensors were calibrated.\nThere were 2 sensors with failing offsets that were not replaced.\nThere were no exceptions.\nHotel is excellent.\n\nThe report and the signed calibration summary is attached.\nI already sent the full report to Kathy.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1xWviax4rIgMoEicIIHqtd1LAjZadUGclRuxpuU3d0-U/edit?usp=sharing','\n',char(10)),'None','Straightforward. 90% on second floor with about 30 on first floor. 7 CO2 sensors all in Microbiology',NULL,'Leighton','2026-08-07 15:02:34','2026-06-30','2026-06-29','2026-07-02');
