INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(124,'Quest','Quest Miramar','921',118,'RE, HU, CO2',0,'G2.0','ARMS',1,'TRUE','Unscheduled',NULL,'Bissen','10200 Commerce Parkway, Miramar, FL 33025','None',NULL,NULL,NULL,'Yes','FLL',NULL,NULL,NULL,NULL,replace('Hi Tuan,\nI’ve completed the calibration. Four sensors failed; I replaced and calibrated them accordingly.\nI noticed that several hardware components appear to be unstable. For example, slight movement of the sensor wires or power cable results in inaccurate readings. Also, it seems that some users have manually adjusted sensor offsets in an attempt to produce correct readings.\nAttached are the full calibration report and the meter certificates used.\nPlease let me know if you require any further information.\n\nThank you,\nBissen','\n',char(10)),'None','These sensors were installed probaly in 2012/13. Most of them are malfunctioning which makes the assignment more difficult than it is. I''ve informed Tuan multiple  times. Also, instead of adjusting the temperature on their equipment, the manipulate the sensors'' offsets after calibration.',NULL,'Bissen','2026-08-07 15:02:34','2026-06-30','2026-06-29','2026-06-30');
