INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(136,'Rooster Bio','Rooster Bio','174',35,'RE, CO2',0,'G2.1','Guardian',1,'TRUE','Unscheduled',NULL,'Fernando','5295 Westview Dr #275, Frederick, MD 21703','None',NULL,NULL,NULL,'no','JFK','Yes','Hilton Garden Inn Frederick','VERY NICE.!',NULL,'1 the AP on the second floor was not working, the sensors for that zone i move to the second AP in order to be calibrated the sensors, and Adan ok the move. ','None','Small job, sensors location are on second floor and first. Adam will take you around ',NULL,'Fernando','2026-08-07 15:02:34','2026-04-07','2026-04-07','2026-04-07');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(137,'Roswell Park','Roswell Park','451',145,'RE, HU, CO2, DP',3,'G2.0','Guardian',1,'TRUE','Unscheduled',NULL,'Bissen','665 Elm St, Buffalo, NY 14203','None',NULL,NULL,NULL,'Yes','BUF','Yes','Wyndham Garden Buffalo Downtown',replace('Hotel is connected to hospital by underground tunnel.\nMeeting Location: CCC building 4th floor, Elm & Carlton Streets, CCC-407\nBuffalo, NY 14263','\n',char(10)),NULL,replace('Support,\n\nThe calibration is complete with four exceptions, but no failures.\nThe O2 sensors have not been installed because they are currently on backorder.\nThe calibration process required two full days to complete. Please schedule three days onsite for future work, especially if additional sensors are installed (they added 30 this year). This will also allow sufficient time for troubleshooting.\n\nThe following CO2 sensors will never display the correct readings because the modules have incorrect power cables installed:\n04.06 37C-6 CO2\n04.04 37C-5 CO2\nI''ve attached a signed copy of the summary.\n\nVisualizer: https://docs.google.com/spreadsheets/d/16VfF9dBgI_m12m0o-lhyJzT2CcwSpk9MNb4Se2mnIxU/edit?usp=sharing','\n',char(10)),'None','Lots of Differential Pressure Sensors and cleanrooms. Customer is very involved in the calibration process. ',NULL,'Bissen','2026-08-07 15:02:34','2025-12-18',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(138,'Santa Barbara Cottage Hospital','Santa Barbara Cottage Hospital','303, 410',421,'RE, HU',0,'G2.1','Mix',4,'TRUE','Unscheduled',NULL,'Daniel, Leighton, Joey, DG','400 W Pueblo St, Santa Barbara, CA 93105','https://www.zeemaps.com/map/nvtxk?group=6798490',NULL,NULL,NULL,'Yes','SBA','No','Best Western Plus Santa Barbara','Fridge and Micro, walkable to the main site, gym sucks though','South Coast Deli, Food at hospital is very good',replace('Find attached a signed copy of the Summary, below is a link for the Visualizer and contact information to provide Report is needed,\n\nVisualizer\nhttps://docs.google.com/spreadsheets/d/1HBH-xGHBW8o7ck-yYD0106rZch4OG6qTH417bO1AN2Q/edit?usp=sharing\n\n Craig Mohan\ncmohan@sbch.org\n\nTyler Rogers\ntrogers@sbch.org\n\nAlfredo Sanchez\na5sanche@sbch.org','\n',char(10)),'Vendormate','Each tech will have an escort and they are normally very well prepared and planned. Usually work 7:30 am to 3 pm. Offsites want to be scheduled a day in advance when you will arrive. Omnicells at main should all have wires in already, you don''t need to bring more than 10 wires',NULL,'Daniel','2026-08-07 15:02:34','2026-06-17','2026-06-15','2026-06-18');
