INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(146,'St. Agnes','St. Agnes','622',190,'RE, HU',0,'G3.0','ARMS',2,'TRUE','Unscheduled',NULL,'Joey, Kyle','900 S Caton Ave, Baltimore, MD 21229','None',NULL,NULL,NULL,'No, service also sucks','BWI','Yes','Holiday Inn Express & Suites Baltimore West - Catonsville, an IHG Hotel','No issues',NULL,replace('The calibration for St. Agnes on server 946 is complete. \nThere was one failure but was replaced with the customers spare.\nThere were 4 exceptions, two due to missing CPs, one due to water damage and one due to bad connectivity in an area preventing the CP from communicating with the AP. We troubleshooted thoroughly to no avail, the customer is aware of all of these issues.\nHotel was good, no complaints on stay or the distance.\n\nThank you,\nLeighton Solomon','\n',char(10)),'Symplr','Max 2 techs. Will need pharmacy escort to get in all the fridges. No service in basement. All lab CP''s need entered in the offline visualizer.',NULL,'Fernando','2026-08-07 15:02:34','2026-06-10','2026-06-08','2026-06-12');
