INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(154,'Texas Heart Institute at St. Lukes','Texas Heart Institute at St. Lukes','799',74,'RE, HU, CO2',0,'G3.0','ARMS',1,'TRUE','Unscheduled',NULL,'Leighton','6770 Bertner Ave, Houston, TX 77030','None',NULL,NULL,NULL,'Yes','IAH, HOU','Yes','Hyatt House Houston Medical Center','Nice! No issues. Paid parking',NULL,replace('The calibration for Texas Heart Institute at St. Lukes on server 999 is complete. 59 out of 60 enabled sensors were calibrated.\nThe one exception was a sensor without a fridge that is currently being replaced.\n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1ipXOpgC7n30-txJv3dqAhwofbRJq1uxBDHzhNEnOF3U/edit?usp=sharing\n\nThank you!\nLeighton','\n',char(10)),'None','Server is EST instead of CST for some reason. 1 tech needed. 13 CO2 sensors. Can be done in a long day. Take Green elevators to 9th floor. 1 sensor is in basement B2 in room P060 by Purple elevators, and the rest are on 9th floor of Denton Cooley building. ',NULL,'Leighton','2026-08-07 15:02:34','2026-02-24','2026-02-23','2026-02-27');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(155,'The Blood Connection','The Blood Connection',NULL,NULL,NULL,NULL,NULL,NULL,2,1,'Unscheduled',NULL,NULL,'1099 Bracken Rd, Piedmont, SC 29673','https://www.zeemaps.com/map/kbcjq?group=5064192 Route 1 West https://www.zeemaps.com/map?group=4443390 Route 2 East https://www.zeemaps.com/map?group=4443585',NULL,NULL,NULL,'101 Kitty Hawk has no Cell Sig. Client blocks VPN.','SAV, RDU, GSP','YES at GSP','Hampton inn  15 park Woodruff drive Greenville SC','No issues','Mezcla over greenville,whole foods.',NULL,'None',replace('Route 2: Arrive on site Monday. Hotel Monday night in Myrtle Beach. Hotel Tuesday night in Raleigh. The rental car will be picked up from SAV and dropped off at RDU.\nStorage Facility - Unit 33 (744 Buffalo Shoals Rd. Statesville, NC 28677) has 1 RM Sensor. It gets replaced by the client yearly. If they want it calibrated for any reason, the gate code is 8512*. The padlock''s combination is 1099.\nSensors previously stored in Unit 33 at the Statesville depot have been relocated to the front desk.','\n',char(10)),NULL,'Bissen','2026-07-31 21:13:23','2026-07-25',NULL,NULL);
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(156,'Trinity Health Oakland Hospital','Trinity Health Oakland Hospital','541',166,'RE, HU',0,'ARMS','ARMS',2,'FALSE','Unscheduled',NULL,'Not Scheduled','44405 Woodard Ave, Pontiac, MI 48341','There are a couple of sensors across the street. Your pharmacy escort will guide you to where they''re located.',NULL,NULL,NULL,'?','DTW',NULL,NULL,NULL,NULL,replace('The calibration at Trinity Health is complete. There are 11 exceptions and five failures. Phil from the pharmacy provided plenty of help. It took three full days to complete this job.\nI''ve attached the signed summary to this email. I''ve also included a link to the visualizer at the bottom.\n\nThanks,\nBissen','\n',char(10)),'None','In 2025, only calibrated Lab and Blood Bank. The pharmacy opted out of the calibration. Dietary is the worst part of this job. Half of their sensors are in some sort of error state.',NULL,'Bissen','2026-08-07 15:02:34',NULL,NULL,NULL);
