INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(176,'UHHS Phase 1','UHHS Phase 1','887, 888, 889, 890, 893, 868',1250,'RE, HU, CO2',5,'Mix','Mix',8,'TRUE','Unscheduled',NULL,'Daniel, Leighton, Joey, Fernando, Matt, Bissen, Kyle, Dejan','11100 Euclid Ave, Cleveland, OH 44106','https://www.zeemaps.com/map/jwokg?group=4984440',NULL,NULL,NULL,'Yes on guest wifi','CLE','Yes','Tru by Hilton Cleveland Midtown','No microwave in room','Cilantro Taqueria, also good food court at main site',replace('Successfully completed a calibration process.\n Few fail sensors and exceptions.\nThank you.\nFernando.\nhttps://docs.google.com/spreadsheets/d/1JSuh-_adcMD70ap8B2sy0PnkzYcNMIu5OYQtXYX1oSc/edit?pli=1&gid=847207410#gid=847207410','\n',char(10)),'Symplr','Largest job, all hands on deck. 13 CO2. Door Code For Core Lab 13799*   Contact Geauga Pharmacy at the start of the week. Cristian Der 440-285-6530. Previous tracker for combined phases: https://docs.google.com/spreadsheets/d/1KGPegP7Yvzw_EU4_aJpcoUgtaTnKJfHvIVJKv0ApXVY/edit?gid=0#gid=0',NULL,'Fernando','2026-08-07 15:02:34','2026-05-20','2026-05-11','2026-05-15');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(177,'UHHS Phase 2','UHHS Phase 2','870, 884, 886, 891, 894, 922',618,'RE, HU',1,'G2.0','Mix',6,'TRUE','Unscheduled',NULL,'Daniel, Leighton, Joey, Fernando, Matt, Bissen, Kyle, Dejan','11100 Euclid Ave, Cleveland, OH 44106','https://www.zeemaps.com/map/kfnsq?group=5142166#',NULL,NULL,NULL,'Yes on Guest Wifi','CLE','Yes',NULL,'No microwaves and gym sucks','Cilantro Taqueria, also great food court at main site',replace('Job is completed 100%\nSome Exceptions and fail sensors.\nFor next year add one extra Technician,  All sites will add more sensors I was inform by Mr. Doyle,\nI did forward a summary never send back with signature, so you can start the final report.\n \nThank you.!\n\nFernando.','\n',char(10)),'Symplr','Lots of offsites, see zeemaps. 6 different servers used, with most sites spread across 4 servers. 5 Techs. Previous tracker for combined phases: https://docs.google.com/spreadsheets/d/1KGPegP7Yvzw_EU4_aJpcoUgtaTnKJfHvIVJKv0ApXVY/edit?gid=0#gid=0',NULL,'Fernando','2026-08-07 15:02:34','2026-05-20','2026-05-18','2026-05-22');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(178,'University of Mississippi (UMMC)','University of Mississippi (UMMC)','150, 153, 179, 955',624,'RE, HU',4,'Mix','Mix',5,'TRUE','Unscheduled',NULL,'Daniel, Leighton, Joey, Fernando, Bissen, Dejan','2500 N State St, Jackson, MS 39216','https://www.zeemaps.com/map/ogegu?group=6981254',NULL,NULL,NULL,'Yes on Guest Wifi','JAN','Yes','Homewood Suites by Hilton Jackson Fondren Medical District','Very nice! Big rooms','Pig and Pint, Roosters, Subway and Chick-fil-A near hospital cafeteria',replace('The calibration for University of Mississippi on server 179 is complete. 527 out of 575 enabled sensors were calibrated.\nThere were 48 exceptions. There were 23 sensors with failing offsets. Please see the attached calibration summary for details.\n\nServer 179 is still a huge problem. It is basically unusable, and the calibrations could not be done live. I know a lot of the issue is from their weak network and their APs running off of wifi, but I want to make sure there is nothing else we can do on our end. We fixed dozens of sensors, calibrated them, and then they all went back to check link or check network. The users of those zones were understandably frustrated at being unable to use Isensix entirely. \n\nThe Biomed department here was recently acquired by Trimedx, so all of their emails have changed.  Please use the emails below moving forward, and keep Brandon in the loop cause he is the main one who handles Isensix.\n\nbrandon.watts@trimedx.com\npaul.fries@trimedx.com\nriazeil.stewart@trimedx.com\n\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/188dLdOTTrf3q5aDjVMRVwOTrdyBlon2YjZH7PTtmBd4/edit?usp=sharing\n\nThank you,\nLeighton','\n',char(10)),'Vendormate','Only good thing about this job is the hotel. LOTS of sensors in Check. APs run off WiFi so servers run behind when calibrating. SID 179 is the Sanderson building and its EXTREMELY slow. 4 O2',NULL,'Bissen','2026-08-07 15:02:34','2026-02-05','2026-02-02','2026-02-06');
INSERT INTO "job_info" ("id","customer","job_name","servers","sensors","meters","o2","server_version","hardware","num_tech","active","status","estimated_days","scheduled_with","site_address","offsites","main_contact","other_contacts","contact_notes","vpn_works","airport_info","emerald_aisle","prev_hotel","hotel_comments","restaurants","report","credentials","comments","other_notes","primary_tech","updated_at","last_calibrated","scheduled_start_date","scheduled_end_date") VALUES(179,'UT Health Tyler','UT Health Tyler','992',105,'RE, HU',0,'G2.0','ARMS',1,'TRUE','Unscheduled',NULL,'Leighton','1000 South Beckham Avenue, Tyler, TX 75701','None',NULL,NULL,NULL,'Yes on ETMCGuest','TYR','No','Staybridge Suites Tyler University Area, an IHG Hotel','No issues','Stanley''s Famous Pit Barbecue!',replace('The calibration for UT Health Tyler on server 992 is complete. 96 of 118 enabled sensors were calibrated. Last years calibrations were cancelled because of their cyber security incident so things have still not recovered for Isensix here. There were 22 exceptions which were mostly CPs stuck in Check Network due to APs being completely missing or nonfunctioning. I fixed a ton of sensors and replaced about 12 sensors that failed.\nNow that I fixed most of the issues minus the missing APs it should take 1 tech about 2 full days to do the job. \n\nThe signed calibration summary is attached.\n\nThe visualizer used for this job is viewable here: \nhttps://docs.google.com/spreadsheets/d/1C6n0D5x4TTCcDAZVjPCbYgT1yL2PP3PR9nW2rDlGfms/edit?usp=sharing\n\nThank you!\n- Leighton','\n',char(10)),'Vendormate','Still recovering from network attack so alot of APs are down or missing. Lab is on 3rd floor, OR in basement need to wear scrubs.  Joesie will take you to all the sensors throughout',NULL,'Leighton','2026-08-07 15:02:34','2026-02-11','2026-02-10','2026-02-13');
